apiRouter.post("/planning/proposals/:id/approve-and-release", async (req, res) => {
  try {
    const actor = typeof req.body?.actor === "string" && req.body.actor.trim() ? req.body.actor.trim() : typeof req.body?.releasedBy === "string" && req.body.releasedBy.trim() ? req.body.releasedBy.trim() : "\u0645\u062F\u06CC\u0631 \u0628\u0631\u0646\u0627\u0645\u0647\u200C\u0631\u06CC\u0632\u06CC \u062A\u0648\u0644\u06CC\u062F";
    if (isDatabaseUrlConfigured()) {
      const rel = await getRelationalPlanProposal(req.params.id);
      if (!rel) return res.status(404).json({ success: false, error: "\u067E\u06CC\u0634\u0646\u0647\u0627\u062F \u0628\u0631\u0646\u0627\u0645\u0647 \u062F\u0631 PostgreSQL \u06CC\u0627\u0641\u062A \u0646\u0634\u062F." });
      if (rel.status === "DRAFT") {
        await approveRelationalPlanProposal(req.params.id, actor);
      }
      const data2 = await releaseRelationalPlanProposal(req.params.id, actor);
      const moNumbers2 = (data2.manufacturingOrders || []).map((m) => m.moNumber);
      return res.status(data2.replayed ? 200 : 201).json({
        success: true,
        message: data2.replayed ? `\u0627\u06CC\u0646 \u067E\u06CC\u0634\u0646\u0647\u0627\u062F \u0642\u0628\u0644\u0627\u064B \u0635\u0627\u062F\u0631 \u0634\u062F\u0647 \u0627\u0633\u062A (\u0628\u0631\u0646\u0627\u0645\u0647 ${data2.plan?.planNumber}).` : `\u067E\u06CC\u0634\u0646\u0647\u0627\u062F \u062A\u0623\u06CC\u06CC\u062F \u0648 \u0628\u0631\u0646\u0627\u0645\u0647 \xAB${data2.plan?.planNumber}\xBB \u0628\u0647 \u0647\u0645\u0631\u0627\u0647 ${moNumbers2.length} \u062F\u0633\u062A\u0648\u0631 \u06A9\u0627\u0631 [${moNumbers2.join("\u060C ")}] \u062F\u0631 PostgreSQL \u0635\u0627\u062F\u0631 \u0634\u062F.`,
        data: data2
      });
    }
    const fb = getFallbackProposal(req.params.id);
    if (!fb) {
      return res.status(404).json({ success: false, error: "\u067E\u06CC\u0634\u0646\u0647\u0627\u062F \u0628\u0631\u0646\u0627\u0645\u0647 \u06CC\u0627\u0641\u062A \u0646\u0634\u062F." });
    }
    if (fb.status === "DRAFT") {
      approveFallbackProposal(req.params.id, actor);
    }
    const data = await releaseFallbackProposal(req.params.id, actor, partsStore, routingsStore);
    await persistProductionWipState();
    await persistInventoryAppState();
    const moNumbers = (data.manufacturingOrders || []).map((m) => m.moNumber);
    return res.status(data.replayed ? 200 : 201).json({
      success: true,
      message: data.replayed ? `\u0627\u06CC\u0646 \u067E\u06CC\u0634\u0646\u0647\u0627\u062F \u0642\u0628\u0644\u0627\u064B \u0635\u0627\u062F\u0631 \u0634\u062F\u0647 \u0627\u0633\u062A (\u0628\u0631\u0646\u0627\u0645\u0647 ${data.plan?.planNumber}).` : `\u067E\u06CC\u0634\u0646\u0647\u0627\u062F \u062A\u0623\u06CC\u06CC\u062F \u0648 \u0628\u0631\u0646\u0627\u0645\u0647 \xAB${data.plan?.planNumber}\xBB \u0628\u0627 \u062F\u0633\u062A\u0648\u0631 \u06A9\u0627\u0631\u0647\u0627\u06CC [${moNumbers.join("\u060C ")}] \u0628\u0647 WIP \u0635\u0627\u062F\u0631 \u0634\u062F.`,
      data
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : "\u062E\u0637\u0627 \u062F\u0631 \u062A\u0623\u06CC\u06CC\u062F \u0648 \u0635\u062F\u0648\u0631 \u0641\u0648\u0631\u06CC \u062F\u0633\u062A\u0648\u0631 \u06A9\u0627\u0631";
    return res.status(/یافت نشد/i.test(message) ? 404 : 409).json({ success: false, error: message });
  }
});
