apiRouter.get("/menus/tree", async (_req, res) => {
  try {
    const prisma = getPrismaClient();
    const rootMenus = await prisma.menu.findMany({
      where: {
        parentId: null,
        isActive: true,
        isDeleted: false
      },
      include: {
        children: {
          where: {
            isActive: true,
            isDeleted: false
          },
          orderBy: {
            orderIndex: "asc"
          }
        }
      },
      orderBy: {
        orderIndex: "asc"
      }
    });
    if (rootMenus && rootMenus.length > 0) {
      return res.json({
        success: true,
        count: rootMenus.length,
        data: rootMenus
      });
    }
    return res.json({
      success: true,
      count: DEFAULT_SYSTEM_MENUS.length,
      data: DEFAULT_SYSTEM_MENUS
    });
  } catch (_error) {
    res.json({
      success: true,
      count: DEFAULT_SYSTEM_MENUS.length,
      data: DEFAULT_SYSTEM_MENUS,
      isFallback: true
    });
  }
});
